Translate("esMX", "kilram", {
	title = "Kilram",
	subtitle = "Forjador de hachas de Vista Eterna",
	found = "Vista Eterna",
	hint = [=[Encuentre al maestro de las hachas de Vista Eterna que lleva una cicatriz.]=],
	allegiance = "Vista Eterna",
	sections = {
		{
			title = "Resumen",
			text = [=[Kilram es un armero que trabaja en {link:everlook}Vista Eterna{/link} junto a Lilith la Ágil y Seril Scourgebane. Lleva una cicatriz en la cara, regalo de la cazadora de las sombras Vosh'gajin, de la Cumbre de {link:blackrock-mountain}Roca Negra{/link}. Ella lo llamó una caricia de amor. Él lo llama una deuda, y piensa cobrarla.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Enseña a fabricar el hacha Filo del {link:alba-fairmoon}Alba{/link} a quienes le traen la piedra de serpiente de Vosh'gajin.]=],
		},
	},
	mentions = {
		{ text = "La piedra de serpiente de la cazadora de las sombras" },
		{ text = "Dulce serenidad, de Lilith la Ágil" },
		{ text = "Corrupción, de Seril Scourgebane" },
	},
})

Translate("esMX", "lorax", {
	title = "Lorax",
	subtitle = "Sátiro de la forja demoníaca",
	found = "Unas ruinas en el sur del Cañón Levescarcha",
	hint = [=[Busque al sátiro que camina de un lado a otro entre ruinas en el sur del cañón.]=],
	allegiance = "Ninguna",
	sections = {
		{
			title = "Resumen",
			text = [=[Lorax es un {link:satyrs}sátiro{/link} que permanece entre ruinas en el sur de {link:winterspring}Cuna del Invierno{/link}. Según sus propias palabras, sus días giran en un lento círculo de dolor, odio y maquinaciones. Conoce el arte de la forja demoníaca. Una vez hizo un trato para enseñárselo a un {link:orcs}orco{/link} {link:blackrock-mountain}Roca Negra{/link} llamado Goraluk Anvilcrack, a cambio de su alma. Goraluk se llevó una coraza sin forjar y huyó a la Cumbre de Roca Negra sin pagar.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Ofrece su saber a quien cobre el alma que le deben.
• Entrega una pica imbuida de energía vil para que beba el alma de Goraluk cuando muera.]=],
		},
	},
	chapters = {
		{
			title = "El trato roto",
			hint = "Escuche la historia del sátiro y salde su deuda.",
			text = [=[Un alma, cualquier alma, vale algo en estos tiempos, dijo Lorax, incluso la de un {link:orcs}orco{/link} {link:blackrock-mountain}Roca Negra{/link}. Cuando la pica volvió manchada con el alma de Goraluk, y con ella la coraza robada, el {link:satyrs}sátiro{/link} cumplió su parte del pacto.]=],
		},
	},
	mentions = {
		{ text = "La historia de Lorax" },
		{ text = "La forja demoníaca" },
	},
})

Translate("esMX", "ranshalla", {
	title = "Ranshalla",
	subtitle = "Buscadora de los lechúcicos",
	found = "Al pie de la loma bajo el Matorral del Ala del Búho",
	hint = [=[Encuentre a la elfa que estudia a los lechúcicos al pie de su loma.]=],
	allegiance = "Elfos de la noche",
	sections = {
		{
			title = "Resumen",
			text = [=[Ranshalla es una elfa de la noche que llegó a {link:winterspring}Cuna del Invierno{/link} a petición de Erelas Ambersky, de la {link:rut-theran-village}Aldea Rut'theran{/link}. Estudia a los lechúcicos en sus propias tierras. Ha explorado las ruinas de {link:lake-kel-theril}Kel'Theril{/link} y ha copiado los conjuros tallados allí. Cree que son la llave de un altar de {red:elune}Elune{/red} en lo alto de la loma de los lechúcicos.]=],
		},
	},
	chapters = {
		{
			title = "Guardianes del altar",
			hint = "Proteja a Ranshalla mientras sube hasta el altar.",
			text = [=[Ranshalla subió la loma y encendió cinco antorchas en las cuevas, recitando las palabras de {link:lake-kel-theril}Kel'Theril{/link} mientras avanzaba. El altar despertó. Mostró que los lechúcicos no eran simples bestias. El archidruida {link:fandral-staghelm}Fandral Staghelm{/link} dijo después que los druidas lo sabían desde hacía mucho: los lechúcicos son criaturas de Elune, elegidas para guardar sus lugares más sagrados.]=],
		},
	},
	mentions = {
		{ text = "Encontrar a Ranshalla" },
		{ text = "Guardianes del altar" },
		{ text = "Los lechúcicos de Elune" },
	},
	bonds = {
		{ id = "erelas-ambersky", name = "Erelas Ambersky", note = "la envió a Cuna del Invierno" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "supo lo que ella encontró" },
	},
})

Translate("esMX", "salfa", {
	title = "Salfa",
	subtitle = "Portavoz de los Fauces de Madera",
	found = [=[Ante la puerta de Cuna del Invierno del Bastión Fauces de Madera]=],
	hint = [=[Hable con el fúrbolg que guarda la puerta de Cuna del Invierno del Bastión Fauces de Madera.]=],
	allegiance = "Fauces de Madera",
	sections = {
		{
			title = "Resumen",
			text = [=[Salfa es un {link:furbolgs}fúrbolg{/link} de los {link:timbermaw-furbolgs}Fauces de Madera{/link} que guarda la puerta de {link:winterspring}Cuna del Invierno{/link} de su bastión. Habla por su tribu en estas tierras. Los Fauces de Madera viven apartados y solo conceden el paso a quienes confían. Salfa mira a los {link:winterfall-furbolgs}Invernales{/link} con dolor. Fueron aliados de los Fauces de Madera hasta que su gran jefe los arrastró a la locura.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Pide ayuda contra los {link:winterfall-furbolgs}Invernales{/link}, con tristeza, pues fueron amigos.
• Acepta las cuentas de espíritu de los Invernales caídos como prueba de ayuda a su tribu.]=],
		},
	},
	mentions = {
		{ text = "Hablar con Salfa" },
		{ text = "Actividad de los {link:winterfall-furbolgs}Invernales{/link}" },
		{ text = "Cuentas para Salfa" },
	},
})

Translate("esMX", "high-chief-winterfall", {
	title = "Gran jefe Invernal",
	subtitle = "Jefe de los fúrbolgs Invernales",
	found = "Poblado Nevada",
	hint = [=[Enfréntese al jefe de los fúrbolgs enloquecidos en su poblado al este de Vista Eterna.]=],
	allegiance = "Fúrbolgs Invernales",
	sections = {
		{
			title = "Resumen",
			text = [=[El gran jefe Invernal gobierna a los fúrbolgs {link:winterfall-furbolgs}Invernales{/link} desde su poblado al este de {link:everlook}Vista Eterna{/link}. Bajo sus órdenes, la tribu se volvió contra sus viejos amigos, los {link:timbermaw-furbolgs}Fauces de Madera{/link}, y empezó a beber el aguardiente verde de {link:felwood}Frondavil{/link}. Llevaba un diario con marcas toscas que nadie en {link:winterspring}Cuna del Invierno{/link} sabía leer.]=],
		},
		{
			title = "Hazañas",
			text = [=[• {link:donova-snowden}Donova Snowden{/link} cree que el cambio de la tribu se produjo por sus órdenes.
• Llevaba un diario de tosca escritura, que se envió al druida {link:kelek-skykeeper}Kelek Skykeeper{/link} para que lo leyera.]=],
		},
	},
	mentions = {
		{ text = "El gran jefe Invernal" },
		{ text = "La última pieza" },
	},
	bonds = {
		{ id = "donova-snowden", name = "Donova Snowden", note = "quería detenerlo" },
		{ id = "salfa", name = "Salfa", note = "habla de sus extrañas exigencias" },
	},
})

Translate("esMX", "shy-rotam", {
	title = "Shy-Rotam",
	subtitle = "Reina de los sables de hielo",
	found = "Roca Sable de Hielo, cuando se la llama",
	hint = [=[Enfréntese a la matriarca de los sables de hielo junto a su piedra.]=],
	allegiance = "Sables de hielo de Cuna del Invierno",
	sections = {
		{
			title = "Resumen",
			text = [=[Shy-Rotam es la matriarca de los sables de hielo de {link:winterspring}Cuna del Invierno{/link}. Los entrenadores de sableinvernales la llaman la reina de los sables de hielo, y piden a sus aliados que luchen en su nombre contra los gigantes Mazo de Escarcha. No acude de buen grado ante los desconocidos. Solo acude furiosa, cuando se deposita la carne de los de su especie sobre su piedra, cerca de la {link:frostsaber-rock}Roca Sable de Hielo{/link}.]=],
		},
	},
	mentions = {
		{ text = "Shy-Rotam" },
		{ text = "Gigantes desbocados" },
	},
	bonds = {
		{ id = "rivern-frostwind", name = "Rivern Frostwind", note = "lucha en su nombre" },
		{ id = "storm-shadowhoof", name = "Storm Shadowhoof", note = "le envía retadores" },
	},
})

Translate("esMX", "artorius-the-amiable", {
	title = "Artorius el Afable",
	subtitle = "Un forastero amistoso",
	found = "Las nieves del norte de Cuna del Invierno",
	hint = "Busque al forastero sonriente en las nieves del norte.",
	allegiance = "Desconocida",
	aliases = { "Artorius" },
	sections = {
		{
			title = "Resumen",
			text = [=[Artorius el Afable es un forastero de buenos modales que vaga por las nieves del norte de {link:winterspring}Cuna del Invierno{/link}. Parece inofensivo. No es lo que parece.]=],
		},
	},
	chapters = {
		{
			title = "El Portador de la Fatalidad",
			hint = "Siga las marcas de la corteza de un anciano hacia el norte.",
			text = [=[{link:vartrus-the-ancient}Vartrus{/link} el Anciano, de {link:felwood}Frondavil{/link}, lo conocía por otro nombre: Artorius el Portador de la Fatalidad, uno de los cuatro corruptores demoníacos de la {link:burning-legion}Legión Ardiente{/link} que aún andan sueltos por {link:kalimdor}Kalimdor{/link}. Allí donde caminan tales agentes, dijo Vartrus, la naturaleza se marchita. Artorius solo abandonaría su disfraz amistoso ante un cazador solitario que viniera a por él.]=],
		},
	},
	mentions = {
		{ text = "El bastón de los Ancestros" },
	},
})

Translate("esMX", "lady-hederine", {
	title = "Lady Hederine",
	subtitle = "Señora de la Garganta Negro Rumor",
	found = "En lo hondo de la Garganta Negro Rumor",
	hint = [=[Enfréntese a la señora demoníaca en el corazón de la Garganta Negro Rumor.]=],
	allegiance = "Legión Ardiente",
	aliases = { "Hederine" },
	sections = {
		{
			title = "Resumen",
			text = [=[Lady Hederine gobierna a los demonios de la {link:darkwhisper-gorge}Garganta Negro Rumor{/link}. Sus seguidores, los iniciados, acechamaná y asesinos Hederine, llevan su nombre. Habitan al pie norte de Hyjal, donde la Legión fue quebrada, aunque ningún registro dice cuándo llegaron. La erudita {link:donova-snowden}Donova Snowden{/link} cree que su presencia envenena la tierra y calienta las fuentes, muy al norte.]=],
		},
	},
})

Translate("esMX", "winterfall-furbolgs", {
	title = "Fúrbolgs Invernales",
	aliases = { "Invernales", "tribu Invernal" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Invernales son la tribu de {link:furbolgs}fúrbolgs{/link} de {link:winterspring}Cuna del Invierno{/link}. No eran un pueblo violento, y durante mucho tiempo fueron aliados de los {link:timbermaw-furbolgs}Fauces de Madera{/link}. Eso ha cambiado. Su gran jefe les ha hecho exigencias extrañas, y ahora caen sobre cualquiera que se acerque, sea bestia o viajero, elfo o goblin. Tienen un poblado en las colinas al este de {link:everlook}Vista Eterna{/link} y campamentos cerca de los {link:frostfire-hot-springs}Baños de Fuego de Escarcha{/link}.]=],
		},
		{
			title = "El aguardiente",
			text = [=[La locura tiene un origen. Los mensajeros de la tribu viajan a través del {link:timbermaw-hold}Bastión Fauces de Madera{/link} hasta los fúrbolgs {link:deadwood-furbolgs}Muertobosque{/link} de {link:felwood}Frondavil{/link}, enloquecidos a su vez por la corrupción vil. Traen de vuelta un brebaje verde hecho con el veneno de los horrores tóxicos del {link:irontree-woods}Bosque de Troncoferro{/link}. Solo, los mataría. Mezclado con el agua de las fuentes termales, pierde su poder mortal pero conserva su fuerza, y quienes lo beben se vuelven más grandes y más salvajes. Por eso los Invernales guardan las fuentes con tanta ferocidad. Los fúrbolgs todavía llevan cuentas de espíritu para ahuyentar a los malos espíritus, pero las cuentas no los han salvado de aquello en lo que se han convertido.]=],
		},
	},
})

Translate("esMX", "crystal-of-zin-malor", {
	title = "Cristal de Zin-Malor",
	sections = {
		{
			title = "Resumen",
			text = [=[El Cristal de Zin-Malor es una reliquia capaz de contener y dominar grandes fuerzas arcanas. Solo los verdaderamente dignos pueden dominarlo, y solo un puñado de los magos más poderosos podría aspirar a ello. Lleva el nombre del {link:temple-of-zin-malor}Templo de Zin-Malor{/link}, que hoy yace en ruinas en {link:azshara}Azshara{/link}. En tiempos antiguos, los Altonato de {link:lake-kel-theril}Kel'Theril{/link} lo robaron con la intención de drenar su poder para sí mismos. En el intento, el cristal estalló con una gran explosión, y sus fragmentos se hundieron bajo el hielo del lago. Los Altonato fueron malditos a permanecer allí para siempre, buscando todavía los fragmentos.]=],
		},
		{
			title = "Recompuesto",
			text = [=[En el presente, el pico de un {link:dwarves}enano{/link} rompió el hielo y sacó cuatro fragmentos. La alta elfa {link:aurora-skycaller}Aurora Skycaller{/link} los reconoció. Con los escritos sagrados de los Altonato, recuperados del templo en ruinas de {link:azshara}Azshara{/link}, recompuso el cristal. Se mostró a un espíritu de {link:lake-kel-theril}Kel'Theril{/link} que se arrepentía del viejo crimen, y ese espíritu encontró la paz. El cristal nunca podría volver a su templo. {link:wynd-nightchaser}Wynd Nightchaser{/link}, de {link:starfall-village}Estrella Fugaz{/link}, lo envió al archidruida {link:fandral-staghelm}Fandral Staghelm{/link} en {link:darnassus}Darnassus{/link}, que elogió a quienes lo llevaron por no intentar usarlo ellos mismos.]=],
		},
	},
})
